import React from 'react';
import { render } from '@testing-library/react-native';
import { GreetingHeader, MULTICOLOR_PALETTES } from './GreetingHeader';

describe('GreetingHeader', () => {
  it('renders greeting text correctly', () => {
    const { getByText } = render(
      <GreetingHeader greetingText="Good Morning" />
    );
    expect(getByText('Good Morning')).toBeTruthy();
  });

  it('resolves multicolor palettes for morning, afternoon, and evening', () => {
    expect(MULTICOLOR_PALETTES.morning).toEqual(['#f43f5e', '#a855f7', '#06b6d4', '#10b981']);
    expect(MULTICOLOR_PALETTES.afternoon).toEqual(['#6366f1', '#06b6d4', '#10b981', '#ec4899']);
    expect(MULTICOLOR_PALETTES.evening).toEqual(['#f97316', '#a855f7', '#3b82f6', '#10b981']);
    expect(MULTICOLOR_PALETTES.default).toEqual(['#f43f5e', '#a855f7', '#06b6d4', '#10b981']);
  });
});
